type Can = (capability: GovernanceCapability) => boolean;
type Props = { section: GovernanceSettingsSection; snapshot: GovernanceSnapshot; run: GovernanceCommandRunner; can: Can; busy: boolean };

function value(form: FormData, key: string): string { return String(form.get(key) ?? "").trim(); }
function lines(input: string): string[] { return [...new Set(input.split(/[\n,]+/).map((item) => item.trim()).filter(Boolean))]; }
function futureIso(days: number): string { return new Date(Date.now() + days * 86_400_000).toISOString(); }
function number(form: FormData, key: string, fallback = 0): number { const parsed = Number(value(form, key)); return Number.isFinite(parsed) ? parsed : fallback; }
function checked(form: FormData, key: string): boolean { return form.get(key) === "on"; }
const LOCALIZED_STATES = new Set(["active", "pending", "pending_verification", "previewed", "queued", "running", "waiting_user", "cancelling", "cancelled", "completed", "completed_hold", "decided", "verified", "locked", "revoked", "resolved", "succeeded", "failed_known", "outcome_unknown", "approved", "denied", "expired", "consumed", "escalated", "released", "cooling_off", "ready", "revalidation_queued", "revalidation_running", "revalidated_allowed", "resolved_upheld"]);

function localizedState(t: ReturnType<typeof useTranslations<"governance">>, state: string): string {
  return t(`states.${LOCALIZED_STATES.has(state) ? state : "unknown"}` as never);
}

function NativeSelect({ id, name, defaultValue, children, required = true, className, ...props }: React.SelectHTMLAttributes<HTMLSelectElement> & { id: string; name: string }) {
  return <select id={id} name={name} required={required} defaultValue={defaultValue} className={`h-9 w-full rounded-md border bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring ${className ?? ""}`} {...props}>{children}</select>;
}

function Field({ id, label, ...props }: React.ComponentProps<typeof Input> & { id: string; label: string }) {
  return <div className="grid gap-1.5"><Label htmlFor={id}>{label}</Label><Input id={id} name={props.name ?? id} {...props} /></div>;
}

function TextArea({ id, label, help, ...props }: React.TextareaHTMLAttributes<HTMLTextAreaElement> & { id: string; label: string; help?: string }) {
  return <div className="grid gap-1.5"><Label htmlFor={id}>{label}</Label><textarea id={id} name={props.name ?? id} {...props} className={`min-h-24 w-full rounded-md border bg-background p-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring ${props.className ?? ""}`} />{help ? <p className="text-xs text-muted-foreground">{help}</p> : null}</div>;
}

function Workflow({ title, description, allowed, busy, children }: { title: string; description: string; allowed: boolean; busy: boolean; children: React.ReactNode }) {
  const t = useTranslations("governance");
  return <details className="group rounded-xl border bg-card" open><summary className="flex cursor-pointer list-none items-start justify-between gap-3 p-4"><span><span className="block font-semibold">{title}</span><span className="mt-1 block text-sm text-muted-foreground">{description}</span></span><ChevronDownIcon className="mt-1 size-4 shrink-0 transition-transform group-open:rotate-180" /></summary><div className="border-t p-4">{allowed ? <fieldset disabled={busy} className="grid gap-4">{children}</fieldset> : <p className="flex items-center gap-2 rounded-lg bg-muted p-3 text-sm text-muted-foreground"><ShieldAlertIcon className="size-4" />{t("permissionRequired")}</p>}</div></details>;
}

function Submit({ label, busy, destructive = false }: { label: string; busy: boolean; destructive?: boolean }) {
  return <Button className="w-fit" type="submit" variant={destructive ? "destructive" : "default"} disabled={busy}>{busy ? <Loader2Icon className="size-4 animate-spin" /> : <CheckIcon className="size-4" />}{label}</Button>;
}

function CapabilityPicker({ selected, onChange }: { selected: GovernanceCapability[]; onChange(value: GovernanceCapability[]): void }) {
  const t = useTranslations("governance");
  return <fieldset className="grid gap-2"><legend className="mb-1 text-sm font-medium">{t("fields.capabilities")}</legend><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{GOVERNANCE_CAPABILITIES.filter((capability) => !RESERVED_ROLE_CAPABILITIES.has(capability)).map((capability) => <label key={capability} className="flex min-h-10 items-center gap-2 rounded-lg border px-3 text-xs" dir="ltr"><input type="checkbox" checked={selected.includes(capability)} onChange={(event) => onChange(event.target.checked ? [...selected, capability] : selected.filter((item) => item !== capability))} />{capability}</label>)}</div></fieldset>;
}

function ApplicationCapabilityPicker({ selected, onChange }: { selected: ApplicationCapabilityReference[]; onChange(value: ApplicationCapabilityReference[]): void }) {
  const t = useTranslations("governance");
  const selectedKeys = new Set(selected.map(applicationCapabilityKey));
  return <fieldset className="grid gap-2"><legend className="mb-1 text-sm font-medium">{t("fields.productCapabilities")}</legend><div className="grid max-h-72 gap-2 overflow-y-auto sm:grid-cols-2 lg:grid-cols-3">{CUSTOM_ROLE_APPLICATION_CAPABILITIES.map((capability) => { const key = applicationCapabilityKey(capability); return <label key={key} className="flex min-h-10 items-center gap-2 rounded-lg border px-3 text-xs" dir="ltr"><input type="checkbox" checked={selectedKeys.has(key)} onChange={(event) => onChange(event.target.checked ? [...selected, capability] : selected.filter((item) => applicationCapabilityKey(item) !== key))} />{key}</label>; })}</div></fieldset>;
}

function RoleBindingFields({ customRoles, binding, onChange, prefix }: { customRoles: GovernanceResource[]; binding: WorkspaceRoleBinding; onChange(value: WorkspaceRoleBinding): void; prefix: string }) {
  const t = useTranslations("governance");
  return <div className="grid gap-3 sm:grid-cols-3"><div className="grid gap-1.5"><Label htmlFor={`${prefix}-binding-kind`}>{t("fields.roleType")}</Label><NativeSelect id={`${prefix}-binding-kind`} name="bindingKind" defaultValue={binding.kind} key={binding.kind} onChange={(event) => onChange(event.currentTarget.value === "custom" ? { kind: "custom", roleId: customRoles[0]?.id ?? "", roleRevision: Number((customRoles[0]?.body as { activeRevision?: number })?.activeRevision ?? 1) } : { kind: "built_in", role: "creator" })}><option value="built_in">{t("fields.builtInRole")}</option><option value="custom" disabled={!customRoles.length}>{t("fields.customRole")}</option></NativeSelect></div>{binding.kind === "built_in" ? <div className="grid gap-1.5 sm:col-span-2"><Label htmlFor={`${prefix}-role`}>{t("fields.role")}</Label><NativeSelect id={`${prefix}-role`} name="role" defaultValue={binding.role} onChange={(event) => onChange({ kind: "built_in", role: event.currentTarget.value as BuiltInWorkspaceRole })}>{BUILT_IN_WORKSPACE_ROLES.filter((role) => role !== "owner").map((role) => <option key={role} value={role}>{t(`roles.${role}`)}</option>)}</NativeSelect></div> : <><div className="grid gap-1.5"><Label htmlFor={`${prefix}-custom-role`}>{t("fields.customRole")}</Label><NativeSelect id={`${prefix}-custom-role`} name="customRole" defaultValue={binding.roleId} onChange={(event) => { const role = customRoles.find((item) => item.id === event.currentTarget.value); onChange({ kind: "custom", roleId: event.currentTarget.value, roleRevision: Number((role?.body as { activeRevision?: number })?.activeRevision ?? 1) }); }}>{customRoles.map((role) => <option key={role.id} value={role.id}>{String((role.body as { name?: string }).name ?? role.id)}</option>)}</NativeSelect></div><Field id={`${prefix}-role-revision`} name="roleRevision" label={t("fields.revision")} type="number" min={1} value={binding.roleRevision} onChange={(event) => onChange({ ...binding, roleRevision: Number(event.currentTarget.value) })} required /></>}</div>;
}

function RoleCatalog() {
  const t = useTranslations("governance");
  return <section aria-labelledby="role-catalog-title"><h3 id="role-catalog-title" className="mb-3 font-semibold">{t("roles.catalog")}</h3><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{BUILT_IN_WORKSPACE_ROLES.map((role) => <article key={role} className="rounded-xl border p-4"><h4 className="font-medium">{t(`roles.${role}`)}</h4><ul className="mt-2 space-y-1 text-xs text-muted-foreground">{BUILT_IN_ROLE_CAPABILITIES[role].map((capability) => <li key={capability} dir="ltr">{capability}</li>)}{BUILT_IN_ROLE_APPLICATION_CAPABILITIES[role].map((capability) => <li key={applicationCapabilityKey(capability)} dir="ltr">{applicationCapabilityKey(capability)}</li>)}</ul></article>)}</div></section>;
}

